$result=Resolve-Safe $ResultPath 'M6-002 result' -Exists;$record=Get-Content -LiteralPath $result -Raw|ConvertFrom-Json;$props=@('schema','task','decision','sdk_version','sdk_commit','build_configuration','route_id','prior_race_restart_result_sha256','seed_source_run_id','seed_source_context','seed_source_log_sha256','seed_source_capture_sha256','seed_save_sha256','seed_header_sha256','signin_compatibility_state','network_services_claimed','probe','release_artifacts','scope');if(($record.PSObject.Properties.Name-join',')-cne($props-join',')-or$record.schema-cne'mcla-garage-lifecycle-v1'-or$record.task-cne'M6-002'-or$record.decision-cne'representative-garage-purchase-customization-persistence-pass'-or$record.sdk_version-cne'0.9.0.22'-or$record.sdk_commit-cne$sdkCommit-or$record.build_configuration-cne'Release'-or$record.route_id-cne'representative-two-process-garage-v1'-or$record.prior_race_restart_result_sha256-cne$priorResultSha-or$record.seed_source_run_id-cne$seedSourceRunId-or$record.seed_source_context-cne'external-owner-identified-hangout-save-after-race-1'-or$record.seed_source_log_sha256-cne$seedSourceLogSha-or$record.seed_source_capture_sha256-cne$seedSourceCaptureSha-or$record.seed_save_sha256-cne$seedSaveSha-or$record.seed_header_sha256-cne$seedHeaderSha-or$record.signin_compatibility_state-ne2-or$record.network_services_claimed-isnot[bool]-or$record.network_services_claimed-or$record.scope-cne$scope){throw 'M6-002 result identity is invalid.'}
